import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardProps, ZimmProductCardImage } from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';

/**
 * `c_productBadges` is a custom SFCC attribute (SFCC-225's own already-merged SCAPI hook) with no
 * typed field on the base SDK's `ProductSearchHit` — it only reaches this shape via that type's
 * own `{[key: string]: any}` index signature. Narrowed here to the one shape this mapper reads,
 * rather than trusting `any` at every call site.
 */
type ProductListSearchHit = ShopperSearchTypes.ProductSearchHit & {
  c_productBadges?: Array<{ productBadge?: string }>;
};

type RawImage = { alt?: string; disBaseLink?: string; link?: string };

const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  if (!src) return undefined;
  return { src, alt: image?.alt ?? '' };
};

/**
 * Picks the image group with the most images as this hit's gallery. Viewpoint-agnostic on
 * purpose — this catalog's real `viewType` naming (e.g. `large` vs `pdp`) was not confirmed for
 * this quick test integration, so "most images" is used as a simple, real-data-driven proxy for
 * "the full gallery" rather than guessing a specific viewType string. Returns `undefined` for 0
 * or 1 resulting images, matching `ZimmProductCardMedia`'s own "no gallery" contract for that
 * case — this function doesn't duplicate that check, it just never returns a 1-length array.
 */
export const selectGalleryImages = (hit: ProductListSearchHit): ZimmProductCardImage[] | undefined => {
  const groups = hit.imageGroups ?? [];
  if (groups.length === 0) return undefined;

  const largest = groups.reduce((best, group) =>
    (group.images?.length ?? 0) > (best.images?.length ?? 0) ? group : best,
  );
  const images = (largest.images ?? []).map(toCardImage).filter((img): img is ZimmProductCardImage => Boolean(img));

  return images.length > 1 ? images : undefined;
};

/**
 * Reads the "size" variation attribute (if this hit has one) into the shape
 * `ZimmSizeChipGroup` expects. `orderable` on each value already reflects real stock per that
 * specific size, so it maps directly to `isDisabled` with no extra lookup needed.
 */
export const selectSizeChipValues = (hit: ProductListSearchHit): ZimmSizeChipValue[] => {
  const sizeAttribute = hit.variationAttributes?.find((attr) => attr.id === 'size');
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/**
 * Maps one real product-search hit to `ZimmProductCardProps` (`variation: 'plp'`) for this quick
 * test integration. `formatPrice` is passed in rather than built here — the page already owns an
 * `intl`-based formatter, and this stays a pure function with no `react-intl` dependency of its
 * own, the same split the page's existing wishlist-toast handlers already follow.
 *
 * Returns `null` when there's no usable name or primary image — mirrors `ZimmProductName`'s own
 * "no render without a name" contract, and `ZimmProductCardBaseProps.primaryImage`'s required-ness
 * (a card with neither has nothing to legitimately render).
 */
export const selectProductListCard = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
): ZimmProductCardProps | null => {
  const primaryImage = toCardImage(hit.image);
  if (!hit.productName || !primaryImage) return null;

  return {
    id: hit.productId,
    href: productUrlBuilder({ id: hit.productId }),
    name: hit.productName,
    headingLevel: 'h3',
    primaryImage,
    images: selectGalleryImages(hit),
    currentPrice: typeof hit.price === 'number' ? formatPrice(hit.price, hit.currency ?? 'USD') : undefined,
    // Deliberately never set for this quick test: a real "Was" price needs pricebook-level
    // discount detection this integration doesn't attempt — flagged rather than guessed, since a
    // wrong "on sale" claim is worse than no claim at all.
    originalPrice: undefined,
    isUnavailable: hit.orderable === false,
    // Single highest-priority badge — SFCC-225's own confirmed shape (see the organism's own
    // docblock, "Badge count" note): only one badge is ever shown, never a list.
    badge: hit.c_productBadges?.[0]?.productBadge,
    variation: 'plp',
    sizeChipValues: selectSizeChipValues(hit),
  };
};

