  });

  test('returns undefined when every group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        { viewType: 'swatch', images: [{ link: 'b.jpg' }] },
