/**
 * Quick test integration only (SFCC-83/84) — swaps the base `ProductTile` for the shared
 * `ZimmProductCard` (`variation: 'plp'`) so it can be exercised against a real PLP grid. Not the
 * final PLP implementation: it still needs the "product card group" component this grid doesn't
 * have yet. Owns its own `selectedSizeChipValue` local state — same pattern
 * `organisms/zimmProductCard/index.stories.tsx`'s own `LiveSizeSelectionCard` already uses —
 * since the page renders many of these and this can't be a single page-level state variable.
 */
type ProductListCardProps = Extract<ZimmProductCardProps, { variation: 'plp' }>;

const ProductListCard = (cardProps: ProductListCardProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(
    () => cardProps.selectedSizeChipValue,
  );
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    cardProps.onSizeChipSelect?.(value);
  };

  return (
    <ZimmProductCard {...cardProps} selectedSizeChipValue={selectedSizeChipValue} onSizeChipSelect={handleSizeChipSelect} />
  );
};

